using System;
using SteamEngine.Common;

namespace SteamEngine.CompiledScripts {

	/// <summary>#962 - Erebor's live recipe for an item written by hand here, generated by the converter into craftrecipes.def.</summary>
	public class CraftRecipeDef : AbstractDef {
		private string item, resources, skillMake;

		public CraftRecipeDef(string defname, string filename, int headerLine)
			: base(defname, filename, headerLine) {
		}

		public override void LoadScriptLines(PropsSection ps) {
			foreach (PropsLine prop in ps.PropsLines) {
				switch (prop.Name.ToLowerInvariant()) {
					case "item":
						this.item = prop.Value;
						break;
					case "resources":
						this.resources = prop.Value;
						break;
					case "skillmake":
						this.skillMake = prop.Value;
						break;
				}
			}
		}

		protected override void On_AfterLoadFromScripts() {
			base.On_AfterLoadFromScripts();
			ItemDef def = ThingDef.GetByDefname(this.item) as ItemDef;
			if (def == null) {
				Logger.WriteWarning(this.Filename, this.HeaderLine, "A recipe for " + this.item + ", which doesn't exist.");
			} else {
				def.SetRecipe(this.Filename, this.HeaderLine, this.resources, this.skillMake);
			}
		}
	}
}
